with latest as (select *, row_number() over (partition by event_type order by event_time desc nulls last, id asc) as latest_rank from web_events qualify latest_rank = 1), base as (select id, session_id, page, event_time, latest_rank, case when event_type = 'add_to_cart' then 1 else 0 end as is_add_to_cart, coalesce(page, 'N/A') as page_filled, coalesce(page, 'OTHER') as page_clean from latest where event_type = 'purchase'), with_windows as (select *, ntile(5) over (order by is_add_to_cart desc, id asc) as is_add_to_cart_bucket, dense_rank() over (partition by session_id order by is_add_to_cart asc nulls first) as is_add_to_cart_dense_rank, ntile(3) over (partition by page, session_id order by is_add_to_cart asc, id asc) as is_add_to_cart_bucket_2 from base), kept_keys as (select id, session_id from with_windows except all select id, session_id from web_events where to_date(event_time) < '2023-07-01'), kept_rows as (select s.* from with_windows s join kept_keys k on s.id = k.id and s.session_id = k.session_id), scored as (select session_id, page, event_time, is_add_to_cart, page_clean, is_add_to_cart_bucket, is_add_to_cart_dense_rank, is_add_to_cart_bucket_2, round(is_add_to_cart_bucket_2 / sum(is_add_to_cart_bucket_2) over (partition by page), 4) as is_add_to_cart_bucket_2_share, avg(is_add_to_cart_dense_rank) over (partition by page order by cast(event_time as bigint) asc range between 2592000 preceding and current row) as is_add_to_cart_dense_rank_avg_30d from kept_rows where is_add_to_cart < 47) select s.session_id, s.page, s.event_time, s.is_add_to_cart, s.is_add_to_cart_bucket_2, s.is_add_to_cart_dense_rank_avg_30d, (select min(w2.duration_sec) from web_events w2 where w2.session_id = s.session_id) as min_web_event_duration_sec from scored s;
